#include <iostream>
#include <vector>

int tribonacci(int n) {
    // first three terms: 0, -1, -1
    if (n == 1) return 0;
    if (n == 2 || n == 3) return -1;

    std::vector<int> seq = {0, -1, -1};
    for (int i = 3; i < n; ++i) {
        seq.push_back(seq[i-1] + seq[i-2] + seq[i-3]);
    }
    return seq[n-1];   // 0‑based index
}

int main() {
    int n;
    std::cout << "Enter the value of n: ";
    std::cin >> n;

    std::cout << "The " << n << "th number in the sequence is: "
              << tribonacci(n) << std::endl;
    return 0;
}
```

